  }
  const text = `📊 Оценено ${scored.length}: ${parts.join(' · ')}${quiet ? `\n🔴 ${quiet} без карточек — теневой режим выключен, они в меню на вкладке ❌` : ''}`;
  messages.push({ text: report ? `${report}\n\n${text}` : text, silent: quiet, report: Boolean(report), live: false });
} else if (report) {
  messages.push({ text: report, silent: true, report: true, live: true });
}

// Тревоги
const alerts = [];
const quota = results.filter((r) => r.outcome === 'quota');
if (quota.length) {
  const provider = quota[0].llm_model?.startsWith('claude') ? 'Claude' : 'Gemini';
  const perDay = quota.some((r) => r.problem === 'day');
  alerts.push(
    `⚠️ ${provider}: ${perDay ? 'исчерпан дневной лимит запросов' : 'превышен лимит запросов в минуту'} (HTTP 429). ` +
      `Не оценено ${quota.length} — оценятся в следующий запуск.` +
      (perDay && provider === 'Gemini' ? '\nЕсли повторяется каждый день — переключить на Claude: ⚙️ Настройки → 🤖 Нейросеть (нужен ANTHROPIC_API_KEY в .env).' : ''),
  );
}
const problems = {};
for (const r of results.filter((x) => x.outcome === 'retry')) problems[r.problem] = (problems[r.problem] ?? 0) + 1;
for (const [problem, n] of Object.entries(problems)) {
  alerts.push(`⚠️ Нейросеть: ${esc(problem)}. Не оценено ${n} — повторю в следующий запуск.`);
}
const failed = sent.filter((s) => !s.result?.message_id);
if (failed.length) {
  alerts.push(`⚠️ Telegram: не отправлено карточек ${failed.length} — ${esc(failed[0].error ?? 'нет ответа')}. Повторю в следующий запуск.`);
}
if (alerts.length) messages.push({ text: alerts.join('\n\n'), silent: false, report: false, live: false });

return messages.map((m) => ({ json: m }));

// W2 · Live report — сообщение о сборе в чате одно: когда пришло новое, прошлое удаляется
// (решение пользователя 07.10.2026).
// Нода: Code, режим «Run Once for All Items».
// Вход: ответы «Send summary» — по одному на сообщение «Summary», в том же порядке.
// Static data: liveId — живое сообщение «🔎 Сбор» в чате. Итог «📊 Оценено» с блоком сбора сверху живым не считается
//   (остаётся вместе с карточками), но прошлое живое сообщение после него тоже удаляется — оно устарело.
// Выход: [{ messageId }] → «Delete report» или [] — удалять нечего.
// Сначала отправка, потом удаление: клавиатура меню едет с новым сообщением. Новое не отправилось — прошлое не трогаем.

const state = $getWorkflowStaticData('global');
const messages = $('Summary')
  .all()
  .map((i) => i.json);
const index = messages.findIndex((m) => m.report);
if (index < 0) return []; // ручной запуск W2 — сбора не было

const id = $input.all()[index]?.json?.result?.message_id;
if (!id) return [];

const old = state.liveId;
state.liveId = messages[index].live ? id : null;
return old && old !== id ? [{ json: { messageId: old } }] : [];

// Recovered — открытые тревоги workflow → «✅ снова работает» (07.10.2026). Код одной ноды в W1 и W2:
// успешный запуск закрывает тревоги своего workflow («Close alerts»).
// Нода: Code, режим «Run Once for All Items». Вход: «Open alerts» — открытые тревоги этого workflow
// (Always Output Data: пустой item, если их нет). Выход: одно сообщение { text } или [] — закрывать нечего.

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.id);
if (!rows.length) return [];

const thai = (ms) => new Date(ms + 7 * 3600 * 1000).toISOString().slice(11, 16);
const hits = rows.reduce((n, r) => n + (Number(r.hits) || 1), 0);
const first = Math.min(...rows.map((r) => Date.parse(r.first_at) || Date.now()));
const last = Math.max(...rows.map((r) => Date.parse(r.last_at) || Date.now()));
const span = thai(first) === thai(last) ? thai(first) : `${thai(first)}–${thai(last)}`;
return [{ json: { text: `✅ <b>${esc(rows[0].workflow)}</b> снова работает: ошибок было ${hits} (${span} по Таиланду)` } }];

// W2 · Release — вернуть в detailed захваченные строки, по которым карточка не ушла (07.10.2026).
// Нода: Code, режим «Run Once for All Items». Своя ветка от триггера, самая нижняя: выполняется последней.
// «Claim» перевёл строки detailed → scoring, чтобы второй запуск W2 не взял их же. Карточка ушла → «Save cards»
// поставил waiting; не ушла (лимит нейросети, сетевая ошибка, Telegram не принял) → строку надо вернуть,
// иначе она застрянет в scoring (такие W6 всё равно вернёт через 30 мин).
// Выход: [{ id }] → «Save release» (status = detailed).

const all = (name) => {
  try {
    return $(name)
      .all()
      .map((i) => i.json);
  } catch {
    return []; // нода в этом запуске не выполнялась
  }
};
// Карточка ушла или skip закрыт без карточки (теневой режим выключен)
const carded = new Set([...all('Card sent'), ...all('Quiet skips')].map((r) => r.id));
return all('Claim')
  .map((r) => r.id)
  .filter((id) => id && !carded.has(id))
  .map((id) => ({ json: { id } }));

// W2 · Run stats — сколько карточек отправил этот запуск → журнал сборов runs (запись W1 «Start run»).
// Нода: Code, режим «Run Once for All Items». Своя ветка от триггера, ниже «Summary»: выполняется последней.
// Вход: $input — item триггера: от W1 { runId, … }, у ручного запуска runId нет;
//       «Send card» — ответы Telegram (выполняется, только если были вакансии на оценку).
// Выход: [{ id, cards }] → «Save run stats» или [] — ручной запуск W2, сбора не было.

const runId = $input.first()?.json?.runId;
if (!runId) return [];

let cards = 0;
try {
  cards = $('Send card')
    .all()
    .filter((i) => i.json.result?.message_id).length;
} catch {
  // карточек в этом запуске не было — нода не выполнялась
}
return [{ json: { id: runId, cards } }];
